const binaryKey = Object.keys($input.item.binary)[0];
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64PDF = pdfBuffer.toString('base64');

const systemPrompt = `You are extracting fields from a Closing Disclosure (CD) PDF for a mortgage loan. Extract EXACTLY these fields and return valid JSON only — no markdown, no explanation.

Required fields:
- borrower_first_name (Page 1 Borrower section)
- cash_to_close (Page 1 Costs at Closing — dollar amount)
- closing_date (Page 1 Closing Information — YYYY-MM-DD format)
- monthly_payment (Page 1 Loan Terms P&I — dollar amount, numbers only)
- property_address (Page 1 Property — full address)
- title_company_name (Page 1 Settlement Agent)
- title_contact_name (Page 5 Contact Information)
- title_phone (Page 5 Contact Information)
- title_email (Page 5 Contact Information)

Return JSON like:
{"borrower_first_name":"John","cash_to_close":"12345.67","closing_date":"2026-03-15","monthly_payment":"1234.56","property_address":"123 Main St, Austin, TX 78701","title_company_name":"ABC Title","title_contact_name":"Jane Smith","title_phone":"512-555-1234","title_email":"jane@abctitle.com"}`;

const userPrompt = 'Extract the closing disclosure fields from this PDF. Return ONLY the JSON object, nothing else.';

const claudeBody = {
  model: 'claude-sonnet-4-5-20251022',
  max_tokens: 2048,
  system: systemPrompt,
  messages: [{
    role: 'user',
    content: [
      { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64PDF } },
      { type: 'text', text: userPrompt }
    ]
  }]
};

return [{ json: { claudeBody, webhookBody: $('Webhook').item.json.body } }];

const raw = $json.content[0].text;
let cd;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  cd = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  throw new Error('Failed to parse Claude response as JSON: ' + raw.substring(0, 200));
}

// Calculate first payment date: closing month + 2
let firstPaymentDate = '[MISSING]';
if (cd.closing_date) {
  const d = new Date(cd.closing_date + 'T00:00:00');
  d.setMonth(d.getMonth() + 2);
  d.setDate(1);
  firstPaymentDate = d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
}

const val = (v) => (v !== null && v !== undefined && v !== '') ? v : '[MISSING]';
const fmt$ = (n) => n ? Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '[MISSING]';
const fmtDate = (d) => {
  if (!d) return '[MISSING]';
  return new Date(d + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
};

return [{ json: {
  borrower_first_name: val(cd.borrower_first_name),
  cash_to_close: fmt$(cd.cash_to_close),
  closing_date: fmtDate(cd.closing_date),
  closing_date_raw: cd.closing_date || '',
  monthly_payment: fmt$(cd.monthly_payment),
  first_payment_date: firstPaymentDate,
  property_address: val(cd.property_address),
  title_company_name: val(cd.title_company_name),
  title_contact_name: val(cd.title_contact_name),
  title_phone: val(cd.title_phone),
  title_email: val(cd.title_email),
  webhookBody: $('Build Claude Request').item.json.webhookBody
}}];

const f = $json;

const subject = `Your Final Closing Numbers \u2013 Action Required Before ${f.closing_date}`;

const html = `<!DOCTYPE html><html><body style="font-family: Arial, sans-serif; font-size: 14px; color: #222222; line-height: 1.6;"><p>Hi ${f.borrower_first_name},</p><p>Great news \u2014 your Closing Disclosure is finalized. Here\u2019s everything you need to know before your closing on ${f.closing_date}.</p><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">FINAL NUMBERS</p><hr style="border: 1px solid #cccccc;"><p>Cash to Close: <strong>$${f.cash_to_close}</strong><br>Closing Date: <strong>${f.closing_date}</strong><br>First Payment Due: <strong>${f.first_payment_date}</strong><br>Monthly Payment (P&amp;I): <strong>$${f.monthly_payment}</strong></p><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">WIRE INSTRUCTIONS \u2014 READ THIS</p><hr style="border: 1px solid #cccccc;"><p>Funds must be sent via wire transfer. Wire is strongly preferred by the title company and ensures same-day funding. If wire is not possible, a cashier\u2019s check made payable to the title company is acceptable \u2014 contact us first before going that route.</p><p style="background-color: #fff3cd; padding: 10px; border-left: 4px solid #ffc107;">\u26a0\ufe0f <strong>WIRE FRAUD WARNING:</strong> Wire fraud is common in real estate transactions. Before sending any wire, call the title company directly using the number below to verbally confirm the instructions. Do not rely solely on emailed wire instructions \u2014 even if they appear to come from us or the title company.</p><p>Title Company: <strong>${f.title_company_name}</strong><br>Contact: <strong>${f.title_contact_name}</strong><br>Phone: <strong>${f.title_phone}</strong><br>Email: <strong>${f.title_email}</strong></p><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">CLOSING DETAILS</p><hr style="border: 1px solid #cccccc;"><p>Date: <strong>${f.closing_date}</strong><br>Location: <strong>${f.title_company_name}</strong><br><em>Please confirm signing location with your realtor.</em></p><p><strong>What to bring:</strong></p><ul><li>Government-issued photo ID</li><li>Proof of wire confirmation (or cashier\u2019s check if applicable)</li><li>Any documents we\u2019ve requested</li></ul><p>Plan for approximately <strong>45\u201360 minutes</strong>.</p><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">WHAT HAPPENS AFTER SIGNING</p><hr style="border: 1px solid #cccccc;"><ul><li>Keys are released after funding \u2014 not immediately after signing</li><li>Funding typically occurs same day or next business day</li><li>Your first mortgage payment is due <strong>${f.first_payment_date}</strong></li><li>Property: <strong>${f.property_address}</strong></li></ul><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">BEFORE YOU CLOSE \u2014 CRITICAL</p><hr style="border: 1px solid #cccccc;"><p>You\u2019re in the final stretch. Please avoid the following until after you have your keys:</p><ul><li>\u274c Do not open any new credit accounts or make large purchases</li><li>\u274c Do not move or transfer large sums of money between accounts</li><li>\u274c Do not change jobs or employment status</li><li>\u274c Do not miss any payments on existing accounts</li></ul><p>Any one of these can delay or derail your closing. We\u2019re too close.</p><hr style="border: 1px solid #cccccc;"><p style="font-weight: bold; font-size: 15px;">ONE LAST THING</p><hr style="border: 1px solid #cccccc;"><p>It has been a pleasure working with you on this. If you feel we earned it, a quick review goes a long way for a small business like ours:</p><ul><li><a href="https://share.google/ddpwv31jI2oqzN5Ia">Leave a Google Review</a></li><li><a href="https://www.zillow.com/lender-profile/adamstyer/">Leave a Zillow Review</a></li></ul><p>And if anyone in your life is buying, selling, or refinancing, I\u2019d love the opportunity to help them the same way.</p><p>Any questions before closing, call or text me directly.</p><p>Adam Styer<br>Mortgage Banker | The Styer Team<br>(512) 956-6010<br>adam@thestyerteam.com<br>NMLS# 513013</p></body></html>`;

return [{ json: { subject, html, to: 'adam@thestyerteam.com', fields: f } }];
